code='''def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Detect solid rectangular outlines and fill their enclosed interiors.
    for r in range(h-2):
        for c in range(w-2):
            x=g[r][c]
