                # 3x3 outline
                if g[r+1][c+1] != x:
                    g[r+1][c+1]=7
    # Larger rectangular frames: interior fill alternates by the interior side length.
    # Find rectangles whose perimeter is one color and whose interior is background.
    # Enumerate candidate bounding rectangles; process only true uniform-color borders.
    for r1 in range(h):
      for r2 in range(r1+2,h):
       for c1 in range(w):
        for c2 in range(c1+2,w):
         x=g[r1][c1]
         if any(g[r1][c]!=x for c in range(c1,c2+1)) or any(g[r2][c]!=x for c in range(c1,c2+1)): continue
         if any(g[r][c1]!=x or g[r][c2]!=x for r in range(r1,r2+1)): continue
         inner=[g[r][c] for r in range(r1+1,r2) for c in range(c1+1,c2)]
         if all(v==inner[0] and v!=x for v in inner):
          fill=7 if (r2-r1-1)%2 else 2
          for rr in range(r1+1,r2):
           for cc in range(c1+1,c2): g[rr][cc]=fill
    return g
